function prng(seed){var a=seed>>>0||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
var R=prng(52501);
var T0=Date.now();/*Signature edition*/
var F=1000,E=200e9,rho=7850,L=1.0,MAXD=0.01,G=8;
var best=null,evaled=0;
for(var i=0;i<G;i++)for(var j=0;j<G;j++){
  var w=0.02+0.18*i/Math.max(G-1,1),h=0.02+0.28*j/Math.max(G-1,1);
  var I=w*Math.pow(h,3)/12,defl=F*Math.pow(L,3)/(3*E*I),mass=rho*L*w*h;
  evaled++;
  if(defl<=MAXD&&(!best||mass<best.mass))best={w:w,h:h,mass:mass,defl:defl};
}
console.log(JSON.stringify({id:"JAH-APX52S-000001",ok:true,metrics:{evaluated:evaled,feasible:!!best,best_mass_kg:best?+best.mass.toFixed(3):null,best_w_m:best?+best.w.toFixed(4):null,best_h_m:best?+best.h.toFixed(4):null,best_defl_m:best?+best.defl.toExponential(2):null},ms:Date.now()-T0}));

